import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import Modal from '../../../components/ui/Modal/Modal';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';
import styles from './ListAdminsPage.module.css';

const ListAdminsPage = () => {
  const [admins, setAdmins] = useState([]);
  const [selectedAdmin, setSelectedAdmin] = useState(null);
  const [isViewModalOpen, setViewModalOpen] = useState(false);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);

  const headers = [
    { key: 'id', label: 'ID' },
    { key: 'name', label: 'Nome' },
    { key: 'email', label: 'Email' },
    { key: 'created_at', label: 'Data de Criação' }
  ];

  const fetchAdmins = async () => {
    try {
      const response = await api.get('/admins');
      const formattedAdmins = response.data.map(admin => ({
        ...admin,
        created_at: new Date(admin.created_at).toLocaleDateString('pt-BR')
      }));
      setAdmins(formattedAdmins);
    } catch (error) {
      console.error("Erro ao buscar administradores:", error);
    }
  };

  useEffect(() => {
    fetchAdmins();
  }, []);

  const handleView = (admin) => {
    setSelectedAdmin(admin);
    setViewModalOpen(true);
  };

  const handleDelete = (admin) => {
    setSelectedAdmin(admin);
    setDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    try {
      await api.delete(`/admins/${selectedAdmin.id}`);
      setDeleteModalOpen(false);
      fetchAdmins(); // Atualiza a lista após a exclusão
    } catch (error) {
      console.error("Erro ao excluir administrador:", error);
      alert("Ocorreu um erro ao excluir.");
    }
  };

  return (
    <ContentWrapper title="Listar Admins Nível 1">
      <Table 
        headers={headers} 
        data={admins} 
        onView={handleView}
        onDelete={handleDelete}
      />

      {/* Modal de Visualização */}
      <Modal 
        isOpen={isViewModalOpen} 
        onClose={() => setViewModalOpen(false)} 
        title="Detalhes do Administrador"
      >
        {selectedAdmin && (
          <div className={styles.modalContent}>
            <p><strong>ID:</strong> {selectedAdmin.id}</p>
            <p><strong>Nome:</strong> {selectedAdmin.name}</p>
            <p><strong>Email:</strong> {selectedAdmin.email}</p>
            <p><strong>Data de Cadastro:</strong> {selectedAdmin.created_at}</p>
            <div className={styles.modalActions}>
              <Button onClick={() => alert('Navegar para editar perfil')}>Editar Perfil</Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Modal de Exclusão */}
      <Modal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setDeleteModalOpen(false)} 
        title="Confirmar Exclusão"
      >
        {selectedAdmin && (
          <div className={styles.modalContent}>
            <p>Tem a certeza de que deseja excluir o administrador <strong>{selectedAdmin.name}</strong>?</p>
            <p>Esta ação não pode ser desfeita.</p>
            <div className={styles.modalActions}>
              <Button variant="secondary" onClick={() => setDeleteModalOpen(false)}>Cancelar</Button>
              <Button variant="danger" onClick={confirmDelete}>Excluir</Button>
            </div>
          </div>
        )}
      </Modal>
    </ContentWrapper>
  );
};

export default ListAdminsPage;
